using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.Text.RegularExpressions;

var builder = WebApplication.CreateBuilder(args);

// Hook: logging providers and configuration sources (e.g. tenant config)
ConfigureHostBuilder(builder);

// Add services to the container
builder.Services.AddControllers()
    .AddNewtonsoftJson();

builder.Services.AddHttpContextAccessor();

// Authentication: hook first; default LZ_AUTH_* Cognito discovery when not handled
var authHandled = false;
ConfigureCustomAuthentication(builder, ref authHandled);
if (!authHandled)
{
    // Discover and register authenticators dynamically
    var defaultRegion = Environment.GetEnvironmentVariable("AWS_REGION") ?? "us-east-1";
    var authenticators = DiscoverAuthenticators(defaultRegion);

    if (authenticators.Count == 0)
    {
        // Fallback to legacy single authenticator if no LZ_AUTH_* variables found
        var legacyUserPoolId = Environment.GetEnvironmentVariable("COGNITO_USER_POOL_ID");
        if (!string.IsNullOrEmpty(legacyUserPoolId))
        {
            authenticators["default"] = new AuthenticatorConfig
            {
                UserPoolId = legacyUserPoolId,
                Region = defaultRegion
            };
            Console.WriteLine("Using legacy COGNITO_USER_POOL_ID configuration");
        }
        else
        {
            throw new InvalidOperationException(
                "No authenticators configured. Set environment variables like: LZ_AUTH_TENANTAUTH_USERPOOLID");
        }
    }

    // Register each discovered authenticator as a named JWT Bearer scheme
    var authBuilder = builder.Services.AddAuthentication();

    foreach (var (authName, config) in authenticators)
    {
        var authority = $"https://cognito-idp.{config.Region}.amazonaws.com/{config.UserPoolId}";

        authBuilder.AddJwtBearer(authName, options =>
        {
            options.Authority = authority;
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = authority,  // Explicitly set ValidIssuer
                ValidateAudience = false,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true
            };

            options.Events = new JwtBearerEvents
            {
                OnMessageReceived = context =>
                {
                    var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();
                    logger.LogDebug("[{AuthName}] OnMessageReceived - Token present: {HasToken}",
                        authName,
                        !string.IsNullOrEmpty(context.Token));
                    return Task.CompletedTask;
                },

                OnAuthenticationFailed = context =>
                {
                    var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();
                    logger.LogWarning("[{AuthName}] Authentication failed. Exception: {ExceptionType} - {Message}\nAuthority: {Authority}\nValidIssuer: {ValidIssuer}",
                        authName,
                        context.Exception?.GetType().Name,
                        context.Exception?.Message,
                        options.Authority,
                        options.TokenValidationParameters.ValidIssuer);

                    if (context.Exception?.InnerException != null)
                    {
                        logger.LogWarning("[{AuthName}] Inner exception: {InnerExceptionType} - {InnerMessage}",
                            authName,
                            context.Exception.InnerException.GetType().Name,
                            context.Exception.InnerException.Message);
                    }

                    return Task.CompletedTask;
                },

                OnTokenValidated = context =>
                {
                    var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();

                    // Log successful validation details
                    var issuer = context.Principal?.Claims.FirstOrDefault(c => c.Type == "iss")?.Value;
                    var subject = context.Principal?.Claims.FirstOrDefault(c => c.Type == "sub")?.Value;
                    var expClaim = context.Principal?.Claims.FirstOrDefault(c => c.Type == "exp")?.Value;

                    logger.LogInformation("[{AuthName}] Token validated successfully. Issuer: {Issuer}, Subject: {Subject}, Exp: {Exp}",
                        authName,
                        issuer,
                        subject,
                        expClaim);

                    // Add lz-authname header when this scheme succeeds
                    if (!context.HttpContext.Request.Headers.ContainsKey("lz-authname"))
                    {
                        context.HttpContext.Request.Headers["lz-authname"] = authName;
                        logger.LogDebug("[{AuthName}] Added lz-authname header to request", authName);
                    }

                    return Task.CompletedTask;
                },

                OnChallenge = context =>
                {
                    var logger = context.HttpContext.RequestServices.GetRequiredService<ILogger<Program>>();
                    logger.LogWarning("[{AuthName}] OnChallenge - Error: {Error}, ErrorDescription: {ErrorDescription}",
                        authName,
                        context.Error,
                        context.ErrorDescription);
                    return Task.CompletedTask;
                }
            };
        });

        Console.WriteLine($"Registered authenticator: {authName} (Region: {config.Region}, Pool: {config.UserPoolId}, Authority: {authority})");
    }

    // Store authenticator names for middleware
    builder.Services.AddSingleton(authenticators.Keys.ToList());
}

// CORS: hook first; default policy when not handled
