            policy.SetIsOriginAllowed(origin =>
                      origin.StartsWith("https://") || origin.StartsWith("http://"))
                  .WithHeaders(
                      "Authorization",
                      "lz-cognito-region",
                      "lz-cognito-userpool-id",
                      "lz-authname")
                  .AllowAnyHeader()
                  .WithMethods(
                      "GET",
                      "HEAD",
                      "PUT",
                      "OPTIONS",
                      "PATCH",
                      "POST",
                      "DELETE")
                  .WithExposedHeaders(
                      "Date",
                      "x-api-id",
                      "lz-cognito-region",
                      "lz-cognito-userpool-id",
                      "lz-authname")
                  .SetPreflightMaxAge(TimeSpan.FromSeconds(600))
                  .DisallowCredentials();
        });
    });
}

// Add health checks
builder.Services.AddHealthChecks();

// Configure services (will be generated)
var startup = new Startup(builder.Configuration);
startup.ConfigureServices(builder.Services);

var app = builder.Build();

// Configure the HTTP request pipeline
if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}

// Hook: middleware that must run before routing (request logging, path rewriting, ...)
ConfigurePipelinePreRouting(app);

app.UseRouting();

app.UseCors();

// Multi-scheme authentication middleware: hook first; default lz-authname
// header-based middleware when not handled
var authMiddlewareHandled = false;
ConfigureAuthenticationMiddleware(app, ref authMiddlewareHandled);
if (!authMiddlewareHandled)
{
    app.Use(async (context, next) =>
    {
        var registeredAuthNames = context.RequestServices.GetService<List<string>>() ?? new List<string>();
        var logger = context.RequestServices.GetRequiredService<ILogger<Program>>();
        var authNameHeader = context.Request.Headers["lz-authname"].FirstOrDefault();

        if (!string.IsNullOrEmpty(authNameHeader))
        {
            // Specific authentication scheme requested
            if (registeredAuthNames.Contains(authNameHeader, StringComparer.OrdinalIgnoreCase))
            {
                logger.LogDebug("Using authentication scheme from header: {AuthName}", authNameHeader);
                var result = await context.AuthenticateAsync(authNameHeader);
                if (result.Succeeded)
                {
                    context.User = result.Principal;
                }
                else
                {
                    logger.LogWarning("Authentication failed for scheme: {AuthName}", authNameHeader);
                }
            }
            else
            {
                logger.LogWarning("Invalid lz-authname specified: {AuthName}", authNameHeader);
                context.Response.StatusCode = 400;
                await context.Response.WriteAsJsonAsync(new
                {
                    error = "Invalid lz-authname",
                    value = authNameHeader,
                    validValues = registeredAuthNames
                });
                return;
            }
        }
        else
        {
            // No lz-authname header - try each registered authenticator until one succeeds
            logger.LogDebug("No lz-authname header found, trying all registered authenticators");

            foreach (var authName in registeredAuthNames)
            {
                var result = await context.AuthenticateAsync(authName);
                if (result.Succeeded)
                {
                    logger.LogInformation("Successfully authenticated with scheme: {AuthName}", authName);
                    context.User = result.Principal;
                    context.Request.Headers["lz-authname"] = authName;
                    break;
                }
                else
                {
                    logger.LogDebug("Authentication failed with scheme {AuthName}: {Failure}",
                        authName, result.Failure?.Message);
                }
            }
        }

        await next();
    });
}

app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();
app.MapHealthChecks("/health");

app.Run();

